class TestRouting:
    """Validate routing decisions and expert selection."""

    def test_router_logits_shape(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Router logits should have shape (batch*seq, n_experts)."""
        x = make_batch(small_config, 2, 4)
        logits = small_moe.router(x)
        assert logits.shape == (8, small_config.n_experts)

    def test_router_softmax_normalized(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Router probabilities should sum to 1 per token."""
        x = make_batch(small_config, 2, 4)
        logits = small_moe.router(x)
        probs = F.softmax(logits, dim=-1)
        assert torch.allclose(probs.sum(dim=-1), torch.ones(8), atol=1e-6)

    def test_top_k_selection(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Top-k indices should have correct shape."""
        x = make_batch(small_config, 2, 4)
        logits = small_moe.router(x)
        top_k_vals, top_k_idx = torch.topk(logits, small_config.top_k, dim=-1)
        assert top_k_idx.shape == (8, small_config.top_k)

    def test_forward_returns_tuple(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Forward should return (output, aux_loss) tuple."""
        x = make_batch(small_config, 2, 4)
        result = small_moe(x)
        assert isinstance(result, tuple)
        assert len(result) == 2

    def test_aux_loss_is_scalar(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Auxiliary loss should be a scalar tensor."""
        x = make_batch(small_config, 2, 4)
        _, aux_loss = small_moe(x)
        assert aux_loss.dim() == 0
        assert aux_loss.dtype == torch.float32

    def test_aux_loss_non_negative(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Auxiliary loss should be non-negative."""
        x = make_batch(small_config, 2, 4)
        _, aux_loss = small_moe(x)
        assert aux_loss.item() >= 0.0


