class TestCapacity:
    """Validate expert capacity constraints."""

    def test_capacity_calculation(self, small_config: MoEConfig):
        """Capacity should be ceil(capacity_factor * tokens_per_expert)."""
        tokens_per_expert = 8 / small_config.n_experts  # 2 tokens per expert
        expected_capacity = math.ceil(small_config.capacity_factor * tokens_per_expert)
        assert expected_capacity >= small_config.min_capacity

    def test_capacity_respected(self, small_moe: SparseMoE, small_config: MoEConfig):
        """No expert should receive more tokens than capacity."""
        x = make_batch(small_config, 4, 8)  # 32 tokens
        small_moe(x)
        # Check internal state if available
        if hasattr(small_moe, "last_capacity"):
            assert small_moe.last_capacity <= math.ceil(
                small_config.capacity_factor * (32 / small_config.n_experts)
            )

    def test_min_capacity_enforced(self):
        """Min capacity should be at least 1."""
        cfg = MoEConfig(d_model=16, d_ff=32, n_experts=8, top_k=1, min_capacity=1)
        moe = SparseMoE(cfg)
        x = torch.randn(1, 1, 16)
        out, _ = moe(x)
        assert out.shape == x.shape


