class TestGradients:
    """Validate gradient flow through the module."""

    def test_backward_computes_grads(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Gradients should flow to all parameters."""
        x = make_batch(small_config, 2, 4)
        out, aux_loss = small_moe(x)
        loss = out.mean() + aux_loss
        loss.backward()

        for name, param in small_moe.named_parameters():
            assert param.grad is not None, f"Missing gradient for {name}"
            assert param.grad.abs().sum() > 0, f"Zero gradient for {name}"

    def test_router_gradients(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Router should receive gradients."""
        x = make_batch(small_config, 2, 4)
        out, aux_loss = small_moe(x)
        loss = out.mean() + aux_loss
        loss.backward()
        assert small_moe.router.weight.grad is not None
        assert small_moe.router.bias.grad is not None

    def test_expert_gradients(self, small_moe: SparseMoE, small_config: MoEConfig):
        """All experts should receive gradients."""
        x = make_batch(small_config, 2, 4)
        out, aux_loss = small_moe(x)
        loss = out.mean() + aux_loss
        loss.backward()
        for i, expert in enumerate(small_moe.experts):
            for name, param in expert.named_parameters():
                assert param.grad is not None, f"Expert {i} missing grad for {name}"

    def test_no_grad_mode(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Inference mode should not require gradients."""
        x = make_batch(small_config, 2, 4)
        with torch.no_grad():
            out, aux_loss = small_moe(x)
        assert out.shape == x.shape
        assert not out.requires_grad


