class TestDeterminism:
    """Validate deterministic behavior with fixed seeds."""

    def test_same_seed_same_output(self, small_config: MoEConfig):
        """Same seed should produce identical outputs."""
        torch.manual_seed(42)
        moe1 = SparseMoE(small_config)
        x = make_batch(small_config, 2, 4)
        out1, _ = moe1(x)

        torch.manual_seed(42)
        moe2 = SparseMoE(small_config)
        out2, _ = moe2(x)

        assert torch.allclose(out1, out2, atol=1e-6)

    def test_different_seeds_different_outputs(self, small_config: MoEConfig):
        """Different seeds should produce different outputs."""
        torch.manual_seed(42)
        moe1 = SparseMoE(small_config)
        x = make_batch(small_config, 2, 4)
        out1, _ = moe1(x)

        torch.manual_seed(43)
        moe2 = SparseMoE(small_config)
        out2, _ = moe2(x)

        assert not torch.allclose(out1, out2, atol=1e-6)


