class TestPerformance:
    """Basic performance smoke tests."""

    def test_forward_time(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Forward pass should complete in reasonable time."""
        import time
        x = make_batch(small_config, 8, 32)
        start = time.time()
        for _ in range(10):
            small_moe(x)
        elapsed = time.time() - start
        assert elapsed < 5.0, f"Forward pass too slow: {elapsed:.2f}s"

    def test_backward_time(self, small_moe: SparseMoE, small_config: MoEConfig):
        """Backward pass should complete in reasonable time."""
        import time
        x = make_batch(small_config, 8, 32)
        start = time.time()
        for _ in range(5):
            out, aux_loss = small_moe(x)
            loss = out.mean() + aux_loss
            loss.backward()
        elapsed = time.time() - start
        assert elapsed < 5.0, f"Backward pass too slow: {elapsed:.2f}s"


